class Solution:
    def canBeEqual(self, s1: str, s2: str) -> bool:
        # Check if the characters in positions 0 and 2 of s1 and s2 can be rearranged to match
        # Similarly for positions 1 and 3
        return sorted([s1[0], s1[2]]) == sorted([s2[0], s2[2]]) and sorted([s1[1], s1[3]]) == sorted([s2[1], s2[3]])
