class Solution:
    def canBeEqual(self, s1: str, s2: str) -> bool:
        # Check even positions (indices 0 and 2)
        s1_evens = [s1[0], s1[2]]
        s2_evens = [s2[0], s2[2]]
        if sorted(s1_evens) != sorted(s2_evens):
            return False
        # Check odd positions (indices 1 and 3)
        s1_odds = [s1[1], s1[3]]
        s2_odds = [s2[1], s2[3]]
        return sorted(s1_odds) == sorted(s2_odds)
