        # Check positions 0 and 2
        s1_0_2 = sorted([s1[0], s1[2]])
        s2_0_2 = sorted([s2[0], s2[2]])
        if s1_0_2 != s2_0_2:
            return False
        # Check positions 1 and 3
        s1_1_3 = sorted([s1[1], s1[3]])
        s2_1_3 = sorted([s2[1], s2[3]])
        return s1_1_3 == s2_1_3
