        max_len = 0

        for x in freq:
            if x == 1:
                count = freq[x]
                if count % 2 == 1:
                    candidate = count
                else:
                    candidate = count - 1
                if candidate > max_len:
                    max_len = candidate
            else:
                current = x
                level = 0
                while True:
                    next_val = current * current
                    if next_val in freq and freq[current] >= 2:
                        level += 1
                        current = next_val
                    else:
                        break
                candidate = 2 * level + 1
                if candidate > max_len:
                    max_len = candidate

        return max_len

