class Solution:
    def isValid(self, word: str) -> bool:
        # Check if the length is at least 3
        if len(word) < 3:
            return False

        # Check if all characters are alphanumeric (digits or letters)
        for c in word:
            if not (c.isalpha() or c.isdigit()):
                return False

        # Check for at least one vowel and one consonant
        vowels = {'a', 'e', 'i', 'o', 'u'}
        vowel_count = 0
        consonant_count = 0

        for c in word:
            if c.isalpha():
                if c.lower() in vowels:
                    vowel_count += 1
                else:
                    consonant_count += 1

        return vowel_count >= 1 and consonant_count >= 1
