class Solution:
    def minimumOperations(self, nums: List[int], target: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0
        d = [target[i] - nums[i] for i in range(n)]
        res = abs(d[0])
        for i in range(1, n):
            diff = d[i] - d[i-1]
            if diff > 0:
                res += diff
        return res
