        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    common = len(sets[i] & sets[j])
                    if common >= k:
                        adj[i].append(j)
        visited = [False] * n
        count = 0
        for i in range(n):
            if not visited[i]:
                count += 1
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
        return count
from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            x_root = find(x)
            y_root = find(y)
            if x_root == y_root:
                return
            if rank[x_root] < rank[y_root]:
                parent[x_root] = y_root
            else:
                parent[y_root] = x_root
                if rank[x_root] == rank[y_root]:
                    rank[x_root] += 1

        for i in range(n):
            for j in range(i + 1, n):
                set_i = set(properties[i])
                set_j = set(properties[j])
                common = set_i & set_j
                if len(common) >= k:
                    union(i, j)

        roots = set()
        for x in range(n):
            roots.add(find(x))

        return len(roots)
from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Precompute the sets for each property list
        sets = [set(arr) for arr in properties]
        parent = list(range(n))

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        # Iterate through all pairs of nodes
        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        # Count the number of unique roots
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
